        let estrin_pow_1 = z * z;
        let estrin_1_0 = estrin_0_0 + estrin_0_1 * estrin_pow_1;
        let estrin_1_1 = estrin_0_2 + estrin_0_3 * estrin_pow_1;
        let estrin_pow_2 = estrin_pow_1 * estrin_pow_1;
        let estrin_2_0 = estrin_1_0 + estrin_1_1 * estrin_pow_2;
        let estrin_pow_3 = estrin_pow_2 * estrin_pow_2;
